1: export const deviceEquality =
2:   (fields) =>
3:   (previous = {}, next = {}) => {
4:     if (previous === next) {
5:       return true;
6:     }
7: 
8:     const previousIds = Object.keys(previous);
9:     if (previousIds.length !== Object.keys(next).length) {
10:       return false;
11:     }
12: 
13:     for (const id of previousIds) {
14:       if (!next[id]) {
15:         return false;
16:       }
17: 
18:       for (const field of fields) {
19:         if (previous[id][field] !== next[id][field]) {
20:           return false;
21:         }
22:       }
23:     }
24: 
25:     return true;
26:   };
