35: const canvasTintImage = (image, color) => {
36:   const canvas = document.createElement('canvas');
37:   canvas.width = image.width * devicePixelRatio;
38:   canvas.height = image.height * devicePixelRatio;
39:   canvas.style.width = `${image.width}px`;
40:   canvas.style.height = `${image.height}px`;
41: 
42:   const context = canvas.getContext('2d');
43: 
44:   context.save();
45:   context.fillStyle = color;
46:   context.globalAlpha = 1;
47:   context.fillRect(0, 0, canvas.width, canvas.height);
48:   context.globalCompositeOperation = 'destination-atop';
49:   context.globalAlpha = 1;
50:   context.drawImage(image, 0, 0, canvas.width, canvas.height);
51:   context.restore();
52: 
53:   return canvas;
54: };
55: 
56: export const prepareIcon = (background, icon, color) => {
57:   const canvas = document.createElement('canvas');
58:   canvas.width = background.width * devicePixelRatio;
59:   canvas.height = background.height * devicePixelRatio;
60:   canvas.style.width = `${background.width}px`;
61:   canvas.style.height = `${background.height}px`;
62: 
63:   const context = canvas.getContext('2d');
64:   context.drawImage(background, 0, 0, canvas.width, canvas.height);
65: 
66:   if (icon) {
67:     const iconRatio = 0.5;
68:     const imageWidth = canvas.width * iconRatio;
69:     const imageHeight = canvas.height * iconRatio;
70:     context.drawImage(
71:       canvasTintImage(icon, color),
72:       (canvas.width - imageWidth) / 2,
73:       (canvas.height - imageHeight) / 2,
74:       imageWidth,
75:       imageHeight,
76:     );
77:   }
78: 
79:   return context.getImageData(0, 0, canvas.width, canvas.height);
80: };
