82: export const reverseCoordinates = (it) => {
83:   if (!it) {
84:     return it;
85:   }
86:   if (Array.isArray(it)) {
87:     if (it.length === 2 && typeof it[0] === 'number' && typeof it[1] === 'number') {
88:       return [it[1], it[0]];
89:     }
90:     return it.map((it) => reverseCoordinates(it));
91:   }
92:   return {
93:     ...it,
94:     coordinates: reverseCoordinates(it.coordinates),
95:   };
96: };
