98: export const geofenceToFeature = (theme, item) => {
99:   let geometry;
100:   if (item.area.indexOf('CIRCLE') > -1) {
101:     const coordinates = item.area
102:       .replace(/CIRCLE|\(|\)|,/g, ' ')
103:       .trim()
104:       .split(/ +/);
105:     const options = { steps: 32, units: 'meters' };
106:     const polygon = turfCircle(
107:       toMapCoordinates(Number(coordinates[1]), Number(coordinates[0])),
108:       Number(coordinates[2]),
109:       options,
110:     );
111:     geometry = polygon.geometry;
112:   } else {
113:     geometry = reverseCoordinates(parse(item.area));
114:     if (map.coordinateSystem) {
115:       geometry = transformGeometry(geometry, gcoord.WGS84, coordinateSystem(map.coordinateSystem));
116:     }
117:   }
118:   return {
119:     id: item.id,
120:     type: 'Feature',
121:     geometry,
122:     properties: {
123:       name: item.name,
124:       color: item.attributes.color || theme.palette.geometry.main,
125:       width: item.attributes.mapLineWidth || 2,
126:       opacity: item.attributes.mapLineOpacity || 1,
127:     },
128:   };
129: };
130: 
131: export const geometryToArea = (geometry) => {
132:   const normalized = map.coordinateSystem
133:     ? transformGeometry(geometry, coordinateSystem(map.coordinateSystem), gcoord.WGS84)
134:     : geometry;
135:   return stringify(reverseCoordinates(normalized));
136: };
137: 
138: export const findFonts = (map) => {
139:   const { glyphs } = map.getStyle();
140:   if (glyphs.startsWith('https://tiles.openfreemap.org')) {
141:     return ['Noto Sans Regular'];
142:   }
143:   if (glyphs.startsWith('https://api.os.uk')) {
144:     return ['Source Sans Pro Regular'];
145:   }
146:   return ['Open Sans Regular', 'Arial Unicode MS Regular'];
147: };
